// Copies the pure business-rule files the api function needs (cities, pricing, shipment statuses)
// from the app into functions/api/src/shared, so the server prices and validates exactly like the app.
// Runs automatically before every `npm run appwrite:push`. Do not edit the copies by hand.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const out = join(root, 'functions/api/src/shared');
mkdirSync(out, { recursive: true });

const HEADER = '// GENERATED by scripts/sync-shared.mjs from the app source. Do not edit; edit the original and push again.\n';
const files = [
  ['src/data/geo.js', 'geo.js', (s) => s],
  ['src/utils/status.js', 'status.js', (s) => s],
  ['src/utils/pricing.js', 'pricing.js', (s) => s
    .replace("import { CITY_MAP } from '../data/geo.js';", "import { CITY_MAP } from './geo.js';")
    .replace("import { FX } from './format.js';", "import { FX } from './fx.js';")],
];
for (const [from, to, fix] of files) {
  writeFileSync(join(out, to), HEADER + fix(readFileSync(join(root, from), 'utf8')));
}
// FX rates only (format.js pulls in date-fns, which the function does not need).
const fx = readFileSync(join(root, 'src/utils/format.js'), 'utf8').match(/export const FX = \{[^}]*\};/)[0];
writeFileSync(join(out, 'fx.js'), `${HEADER}${fx}\nexport const toPKR = (amount, from = 'PKR') => (Number(amount) || 0) * (FX[from] || 1);\n`);
console.log('shared rules copied to functions/api/src/shared');
